-- As patentes ganharam níveis: 83 degraus no lugar de 10. A patente vista passa para a escala nova,
-- igual ao degrau atual de cada um, para o sino não avisar de uma subida que não aconteceu.
UPDATE "usuarios" SET "patente_vista" = (
  SELECT count(*) FROM (VALUES (0), (600), (1250), (1900), (2600), (3300), (4050), (4850), (5650), (6500), (7400), (8350), (9300), (10300), (11350), (12450), (13600), (14800), (16050), (17400), (18800), (20250), (21750), (23350), (25000), (26750), (28550), (30450), (32400), (34450), (36600), (38850), (41200), (43650), (46200), (48900), (51700), (54650), (57700), (60900), (64250), (67750), (71400), (75200), (79200), (83350), (87700), (92250), (97000), (101950), (107150), (112550), (118200), (124100), (130300), (136750), (143500), (150550), (157950), (165650), (173700), (182100), (190900), (200100), (209700), (219750), (230250), (241200), (252650), (264600), (277100), (290150), (303800), (318050), (332950), (348550), (364850), (381850), (399650), (459650), (549650), (699650), (1099650)) AS degraus(xp) WHERE degraus.xp <= "usuarios"."xp_total"
);
